    image_patch = ImagePatch(image)
    car_patches = image_patch.find("white car")
    roundabout_patches = image_patch.find("roundabout")

    if not car_patches or not roundabout_patches:
        return car_patches

    near_cars = []
    for car in car_patches:
        for roundabout in roundabout_patches:
            if distance(car, roundabout) < 0.5:  # Assuming a threshold of 0.5 for "near"
                near_cars.append(car)
                break

    return near_cars

